    return "CRootOf(%s, %d)" % (self._print_Add(expr.expr, order='lex'),
                                expr.index)

def _print_RootSum(self, expr):
    args = [self._print_Add(expr.expr, order='lex')]

    if expr.fun is not S.IdentityFunction:
        args.append(self._print(expr.fun))

