class Option(object):
    """Base class for all kinds of options. """

    option = None

    is_Flag = False

    requires = []
    excludes = []

    after = []
    before = []

    @classmethod
    def default(cls):
        return None

    @classmethod
    def preprocess(cls, option):
        return None

    @classmethod
    def postprocess(cls, options):
